import { getModelEntry, unregisterModel } from '../../../server/bare/registry/model-registry.js';
import { getRPC } from '../../../server/bare/delegate-rpc-client.js';
import { send } from '../../../server/rpc/delegate-transport.js';
import { hasActiveProviders } from '../../../server/bare/hyperswarm.js';
import { getRegistryStats } from '../../../server/bare/registry/model-registry.js';
import { ModelIsDelegatedError } from '../../../utils/errors-server.js';
import { getServerLogger } from '../../../logging/index.js';
const logger = getServerLogger();
export async function handleUnloadModelDelegated(request) {
    const entry = getModelEntry(request.modelId);
    if (!entry?.isDelegated) {
        throw new ModelIsDelegatedError(request.modelId);
    }
    const { providerPublicKey, timeout, healthCheckTimeout } = entry.delegated;
    unregisterModel(request.modelId);
    try {
        logger.info(`Sending delegated unload for model ${request.modelId} to provider: ${providerPublicKey}`);
        const rpc = await getRPC(providerPublicKey, { timeout, healthCheckTimeout });
        await send({ type: 'unloadModel', modelId: request.modelId, clearStorage: false }, rpc, { timeout, peerKey: providerPublicKey });
        logger.info(`Delegated model ${request.modelId} unloaded on provider`);
    }
    catch (error) {
        logger.error(`Failed to unload delegated model ${request.modelId} on provider:`, error);
    }
    const stats = getRegistryStats();
    return {
        type: 'unloadModel',
        success: true,
        hasActiveModels: stats.totalModels > 0,
        hasActiveProviders: hasActiveProviders()
    };
}
